import { useEffect, useState } from "react";
import { motion } from "framer-motion";

const branches = ["Nava India", "RS Puram", "Kovaipudur"];

export default function Gallery() {
  const [branch, setBranch] = useState("Nava India");
  const [images, setImages] = useState([]);

  useEffect(() => {
    fetch(`http://localhost:5000/gallery?branch=${branch}`)
      .then((res) => res.json())
      .then((data) => setImages(data));
  }, [branch]);

  const downloadImage = async (url) => {
    const res = await fetch(url);
    const blob = await res.blob();
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "bodyzeal.jpg";
    link.click();
  };

  return (
    <section className="bg-black py-24 px-6">
      <div className="max-w-7xl mx-auto">
        <h2 className="text-4xl text-center font-bold mb-12">
          Our <span className="text-yellow-400">Gallery</span>
        </h2>

        {/* FILTER */}
        <div className="flex justify-center gap-4 mb-12">
          {branches.map((b) => (
            <button
              key={b}
              onClick={() => setBranch(b)}
              className={`px-6 py-2 rounded-full border ${
                branch === b
                  ? "bg-yellow-400 text-black"
                  : "border-yellow-400 text-yellow-400"
              }`}
            >
              {b}
            </button>
          ))}
        </div>

        {/* GRID */}
        <div className="grid md:grid-cols-3 gap-8">
          {images.slice(0, 6).map((img, i) => (
            <motion.div
              key={img.id}
              whileHover={{ scale: 1.05 }}
              className="relative overflow-hidden rounded-2xl"
            >
              <img
                src={`http://localhost:5000${img.image_url}`}
                className="w-full h-72 object-cover"
              />
              <button
                onClick={() =>
                  downloadImage(
                    `http://localhost:5000${img.image_url}`
                  )
                }
                className="absolute bottom-4 right-4 bg-yellow-400 px-4 py-1 rounded-full text-black"
              >
                Download
              </button>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
